import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

/** The golden vectors (generated by scripts/vectors/gen-org-root-v1.mjs). Typed loosely: tests narrow per section. */
// biome-ignore lint/suspicious/noExplicitAny: fixture sections are read by shape, not by a schema
export const kat: any = JSON.parse(
	readFileSync(
		fileURLToPath(new URL("../fixtures/org-root-v1.json", import.meta.url)),
		"utf8",
	),
);

export const unhex = (text: string): Uint8Array =>
	new Uint8Array(Buffer.from(text, "hex"));

export const hex = (bytes: Uint8Array): string =>
	Buffer.from(bytes).toString("hex");
